void
gtk_css_section_unref (GtkCssSection *section)
{
	g_return_if_fail (section != NULL);

	section->ref_count -= 1;
	if (section->ref_count > 0)
		return;

	if (section->parent)
		gtk_css_section_unref (section->parent);
	if (section->file)
		g_object_unref (section->file);

	g_free (section);
}

